import axios from "axios";

const API = axios.create({ baseURL: "http://localhost:3001" }); // Replace with your backend URL

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("token"); // Get the token from localStorage
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Update Exam Data APIs for a franchise
// Function to update exam data
export const updateExamData = async (exam) => {
    const { franchiseId, _id, ...examData } = exam; // Ensure franchiseId and _id are available
    if (!franchiseId || !_id) {
        throw new Error('Invalid franchiseId or examId');
    }

    // Ensure the token is being sent along with the request
    const token = localStorage.getItem("token");

    if (!token) {
        throw new Error("No token found");
    }

    const url = `http://localhost:3001/franchises/${franchiseId}/exam-data/${_id}`;

    // Send the PUT request with the token in headers
    return axios.put(url, examData, {
        headers: {
            Authorization: `Bearer ${token}` // Attach the token here
        }
    });
};

// Function to delete exam data by ID
export const deleteExamData = (franchiseId, examId) =>
    API.delete(`/franchises/${franchiseId}/exam-data/${examId}`);
